import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures availability before rendering
const { fontFamily: interFamily } = loadInter();



export type DigitalCard3DProps = Record<string, any>;

const DigitalCard3D: React.FC<DigitalCard3DProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  phoneColor = "#D4ED1A",
  cardColor = "#D4ED1A",
  brandName = "MONEYME",
  tagline = "Cashback Rewards",
  cardNumber = "•••• 1234",
  textColor = "#081C15",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // 1. Core Background Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 2. Animation Timelines & Springs
  // Entrance animation: Phone flies in and settles
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1, stiffness: 80 },
  });

  // Pop animation: Card floats out of the screen (starts after entrance)
  const popFrame = Math.max(0, frame - 35);
  const cardPopProgress = spring({
    frame: popFrame,
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 90 },
  });

  // 3. 3D Spatial Interpolations
  // Phone rotates from a dramatic side angle to a readable resting angle
  const phoneRotY = interpolate(entranceProgress, [0, 1], [-85, -22]);
  const phoneRotX = interpolate(entranceProgress, [0, 1], [30, 12]);
  const phoneScale = interpolate(entranceProgress, [0, 1], [0.4, 0.95]);

  // Card translates in Z space (popping out) and gets a slight extra twist
  const cardZ = interpolate(cardPopProgress, [0, 1], [2, 180]);
  const cardRotY = interpolate(cardPopProgress, [0, 1], [0, 8]);
  const cardRotX = interpolate(cardPopProgress, [0, 1], [0, 4]);

  // Continuous breathing motion
  const breathY = Math.sin(frame / 35) * 12;
  const breathX = Math.cos(frame / 45) * 6;

  // 4. Dimensions & Layout Math
  const phoneWidth = 460;
  const phoneHeight = 920;
  const extrusionDepth = 18; // Number of stacked layers
  const zStep = 2; // Distance between each layer
  const screenTopOffset = -425; // Center of screen relative to phone center
  const slotTop = 130; // Distance from screen top to card slot
  const cardHeight = 240;
  const cardYCenterOffset = screenTopOffset + slotTop + (cardHeight / 2); // Exact Y pos for the floating card

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      {/* 
        Main 3D Stage 
        Requires high perspective to make the card "pop" dramatic 
      */}
      <div style={{
        position: "absolute", inset: 0,
        perspective: "1600px",
        display: "flex", justifyContent: "center", alignItems: "center"
      }}>
        
        {/* The Preserve-3D Container holding all geometries */}
        <div style={{
          position: "absolute",
          transformStyle: "preserve-3d",
          transform: `translate3d(${breathX}px, ${breathY}px, 0) scale(${phoneScale}) rotateX(${phoneRotX}deg) rotateY(${phoneRotY}deg)`,
        }}>

          {/* --- PHONE BODY EXTRUSION --- */}
          {/* We loop to create a stack of layers simulating a solid 3D block */}
          {Array.from({ length: extrusionDepth }).map((_, i) => {
            const isFront = i === extrusionDepth - 1;
            const zOffset = -(extrusionDepth - 1 - i) * zStep;
            // Middle layers get a black overlay to simulate shadow/shading
            const overlayOpacity = isFront ? 0 : 0.15;

            return (
              <div key={`layer-${i}`} style={{
                position: "absolute",
                width: phoneWidth, height: phoneHeight,
                backgroundColor: phoneColor,
                borderRadius: 65,
                transform: `translate(-50%, -50%) translateZ(${zOffset}px)`,
                transformStyle: "preserve-3d",
              }}>
                <div style={{ position: "absolute", inset: 0, backgroundColor: `rgba(0,0,0,${overlayOpacity})`, borderRadius: "inherit" }} />

                {/* Hardware Buttons attached to middle layer */}
                {!isFront && i === Math.floor(extrusionDepth / 2) && (
                  <>
                    <div style={{ position: "absolute", right: -5, top: 280, width: 10, height: 110, backgroundColor: "rgba(0,0,0,0.2)", borderRadius: "0 5px 5px 0" }} />
                    <div style={{ position: "absolute", right: -5, top: 410, width: 10, height: 70, backgroundColor: "rgba(0,0,0,0.2)", borderRadius: "0 5px 5px 0" }} />
                  </>
                )}

                {/* Front Face: Contains the screen and bezel */}
                {isFront && (
                  <div style={{ position: "absolute", inset: 0, display: "flex", justifyContent: "center", alignItems: "center" }}>
                    {/* Black Bezel */}
                    <div style={{ width: 420, height: 880, backgroundColor: "#111", borderRadius: 50, display: "flex", justifyContent: "center", alignItems: "center", boxShadow: "inset 0 0 10px rgba(255,255,255,0.1)" }}>
                      {/* White Screen */}
                      <div style={{ width: 390, height: 850, backgroundColor: "#ffffff", borderRadius: 35, position: "relative", overflow: "hidden" }}>
                        
                        {/* iOS Status Bar */}
                        <div style={{ position: "absolute", top: 15, left: 24, right: 24, display: "flex", justifyContent: "space-between", alignItems: "center", zIndex: 10 }}>
                          <span style={{ fontSize: 16, fontWeight: 500, color: "#000" }}>12:34</span>
                          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
                            {/* Signal */}
                            <svg width="20" height="14" viewBox="0 0 20 14" fill="black">
                              <rect x="1" y="10" width="3" height="4" rx="1"/>
                              <rect x="6" y="7" width="3" height="7" rx="1"/>
                              <rect x="11" y="4" width="3" height="10" rx="1"/>
                              <rect x="16" y="0" width="3" height="14" rx="1"/>
                            </svg>
                            {/* WiFi (Simplified Arc) */}
                            <svg width="18" height="14" viewBox="0 0 18 14" fill="none" stroke="black" strokeWidth="2.5" strokeLinecap="round">
                              <path d="M2 9 C 6 5, 12 5, 16 9" />
                              <path d="M5 12 C 8 9.5, 10 9.5, 13 12" />
                            </svg>
                            {/* Battery */}
                            <svg width="26" height="14" viewBox="0 0 26 14" fill="none">
                              <rect x="1" y="1" width="20" height="12" rx="3" stroke="black" strokeWidth="1.5"/>
                              <rect x="3" y="3" width="14" height="8" rx="1" fill="black"/>
                              <path d="M24 5 V 9" stroke="black" strokeWidth="2" strokeLinecap="round"/>
                            </svg>
                          </div>
                        </div>

                        {/* App Interface Placeholder (Below Card) */}
                        <div style={{ position: "absolute", top: 420, left: 20, right: 20 }}>
                           <div style={{ width: "60%", height: 24, backgroundColor: "#f0f0f0", borderRadius: 6, marginBottom: 16 }} />
                           <div style={{ width: "100%", height: 80, backgroundColor: "#f9f9f9", borderRadius: 16, marginBottom: 12 }} />
                           <div style={{ width: "100%", height: 80, backgroundColor: "#f9f9f9", borderRadius: 16 }} />
                        </div>

                        {/* Ghost Slot: Shows where the card rests when flush with screen */}
                        <div style={{
                          position: "absolute",
                          top: slotTop, left: 20, right: 20, height: cardHeight,
                          borderRadius: 20,
                          backgroundColor: "#f5f5f5",
                          border: `2px dashed ${phoneColor}66`,
                          opacity: interpolate(cardPopProgress, [0, 0.5], [0, 1]),
                        }} />
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}

          {/* --- FLOATING 3D DIGITAL CARD --- */}
          {/* This must be a sibling to the phone layers to avoid overflow clipping issues in CSS 3D */}
          <div style={{
            position: "absolute",
            width: 350, height: cardHeight,
            // Positioned perfectly over the screen slot, then translated in Z
            transform: `translate(-50%, -50%) translateY(${cardYCenterOffset}px) translateZ(${cardZ}px) rotateY(${cardRotY}deg) rotateX(${cardRotX}deg)`,
            transformStyle: "preserve-3d",
          }}>

            {/* Glowing Aura Filter Behind Card (Only visible when popped) */}
            <div style={{
              position: "absolute", inset: -20,
              backgroundColor: cardColor, filter: "blur(35px)",
              opacity: interpolate(cardPopProgress, [0.3, 1], [0, 0.45]),
              transform: "translateZ(-10px)",
              borderRadius: 30,
            }} />

            {/* Main Card Surface */}
            <div style={{
              position: "absolute", inset: 0,
              backgroundColor: cardColor,
              borderRadius: 20,
              padding: 24,
              display: "flex", flexDirection: "column", justifyContent: "space-between",
              boxShadow: `0 20px 40px rgba(0,0,0,${interpolate(cardPopProgress, [0, 1], [0, 0.15])})`,
              overflow: "hidden",
            }}>
              
              {/* Header: Brand & Label */}
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", zIndex: 2 }}>
                <span style={{ 
                  fontSize: 28, fontWeight: 900, fontStyle: "italic", 
                  letterSpacing: "-1px", color: textColor,
                  transform: `scale(${interpolate(cardPopProgress, [0, 1], [0.95, 1])})`,
                }}>
                  {brandName}
                </span>
                <span style={{ fontSize: 13, fontWeight: 500, color: textColor, opacity: 0.9 }}>
                  {tagline}
                </span>
              </div>

              {/* Footer: Number & Logo */}
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", zIndex: 2 }}>
                <span style={{ fontSize: 18, fontWeight: 600, color: textColor, letterSpacing: "1px" }}>
                  {cardNumber}
                </span>
                
                {/* Minimalist Payment Logo (Mastercard style overlapping circles) */}
                <div style={{ display: "flex", position: "relative", width: 52, height: 32 }}>
                  <div style={{ position: "absolute", left: 0, width: 32, height: 32, borderRadius: "50%", backgroundColor: "#EB001B", zIndex: 1 }} />
                  {/* Using opacity instead of mixBlendMode for safer cross-platform rendering */}
                  <div style={{ position: "absolute", right: 0, width: 32, height: 32, borderRadius: "50%", backgroundColor: "#F79E1B", zIndex: 2, opacity: 0.9 }} />
                </div>
              </div>

              {/* Holographic Scanning Line Effect */}
              {/* Runs a bright line down the card continuously once popped */}
              <div style={{
                position: "absolute", left: 0, right: 0, height: 3,
                backgroundColor: "rgba(255,255,255,0.9)",
                boxShadow: "0 0 15px 8px rgba(255,255,255,0.4)",
                top: `${interpolate((frame - 35) % 180, [0, 180], [-20, 120], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })}%`,
                opacity: interpolate(cardPopProgress, [0.5, 1], [0, 0.85]),
                zIndex: 5,
              }} />
              
              {/* Subtle digital noise overlay (Simulated via linear-gradient stripes) */}
              <div style={{
                position: "absolute", inset: 0,
                backgroundImage: "linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px)",
                backgroundSize: "100% 4px",
                opacity: interpolate(cardPopProgress, [0.5, 1], [0, 1]),
                zIndex: 1,
                pointerEvents: "none"
              }} />

            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DigitalCard3D;